{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.00) to correct for overestimation bias.",
    "Reduce forecast peaks by 5-10% after a spike in price, to mitigate overshoot and avoid overreaction to short-term volatility.",
    "Apply mean reversion correction: if forecast deviates > ±10% from 15-day moving average, adjust toward the average.",
    "Increase forecast lag by 1-2 days when sentiment is positive (sentiment > 0.00) to account for delayed market response.",
    "When sentiment is positive and price is trending upward, reduce forecast slope to avoid over-optimism.",
    "For long-term (30-day) forecasts, apply smoothing: if true outcome deviates > 15% from forecast, adjust next forecast toward true outcome by 30% of the deviation."
  ]
}
